def refs():
    return [{**s, "subject": "science", "locator": "有機物分子式、結構式、同分異構物、官能基、物性比較與模型判讀", "observedPattern": "公開學校理化試題常以分子式／模型比較、甲醚與乙醇等生活有機物及性質資料，要求判斷組成與原子連接的關係；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-cb-iv-3-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": "A", "explanation": explanation + "選 A。"}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開理化科資料僅供分子式、結構式、同分異構物、官能基與物性推理的能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公立學校公開理化科資料的能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "分子式 C₂H₆O 的資訊範圍，下列哪一項說法最正確？", {"A": "它告訴我們元素種類與各元素原子數，但未單獨指定原子連接方式", "B": "它直接畫出每一條化學鍵的方向", "C": "它保證所有 C₂H₆O 樣品都是同一種物質", "D": "它可以單獨決定樣品的沸點與氣味"}, "分子式是組成的摘要，不能單獨呈現原子如何相連，也不能由此直接決定全部物性。", "先分辨分子式提供的資訊，再列出需要結構式或實驗資料補充的部分。", ["讀取 C₂H₆O 中的元素種類。", "讀取每種元素的原子數。", "檢查式子是否呈現原子彼此的連接方式。", "確認沸點與氣味還需要結構和實驗資料。", "所以選 A。"], "easy"),
    make(2, "乙醇 CH₃CH₂OH 與二甲醚 CH₃OCH₃ 具有相同分子式時，最重要的差異是？", {"A": "氧原子在兩者中的連接位置不同，形成不同的結構", "B": "乙醇比二甲醚多一個氧原子", "C": "兩者只差在分子式下標的寫法，原子連接完全相同", "D": "其中一種不是由碳、氫、氧組成"}, "兩個式子都可數出 C₂H₆O，但乙醇有 C—O—H 的羥基連接，二甲醚為 C—O—C；差異在連接方式。", "先逐項數原子，再比較氧原子連接到誰，避免只看名稱或書寫順序。", ["數乙醇的碳、氫、氧原子。", "數二甲醚的碳、氫、氧原子。", "分別標出氧原子兩側連接的原子。", "判斷組成相同但連接不同。", "所以選 A。"], "medium"),
    make(3, "兩個模型含有相同數量的 C、H、O 原子，卻要判斷是否為同分異構物，還必須檢查什麼？", {"A": "原子間的連接關係是否真的不同，而非只把模型旋轉或換角度", "B": "模型使用的顏色是否完全相同", "C": "兩個樣品的質量是否一定不同", "D": "分子式中的元素符號是否改成另一種語言"}, "同分異構物要求分子式相同且結構不同；旋轉同一模型不會產生新物質。", "先確認『同分子式』，再排除只改變觀察角度的假差異。", ["比較兩模型的元素種類與原子數。", "追蹤每個關鍵原子實際連接的對象。", "把整個模型旋轉或翻面不算新連接。", "只有連接關係改變才支持結構不同。", "所以選 A。"], "medium"),
    make(4, "若甲、乙的分子式相同，甲的沸點明顯較高，哪一種解釋最符合本單元的推理方式？", {"A": "可能因結構造成分子間作用不同，但還要以結構與其他資料交叉檢查", "B": "只要沸點不同，就能確定兩者含有不同元素", "C": "沸點高低與原子排列和分子間作用完全無關", "D": "分子式相同時，沸點差異一定是測量錯誤"}, "相同組成仍可能有不同結構與分子間作用，沸點差異可作為線索，但不能單靠一項資料直接完成鑑定。", "把觀察、合理模型與尚需驗證的限制分開寫。", ["記錄已知的共同分子式。", "把沸點差異當作觀察結果而非結論。", "提出結構或分子間作用不同的假設。", "尋找結構式、溶解性或其他重複資料交叉檢查。", "所以選 A。"], "hard"),
    make(5, "下列哪一項最能說明為何不能把分子式的書寫順序當成實際鍵結順序？", {"A": "分子式只列出組成總數，結構式才用連線呈現原子的相鄰關係", "B": "所有分子中的原子都沒有固定連接", "C": "化學式中的下標只代表分子的顏色", "D": "只要把符號左右交換，就一定生成另一種物質"}, "分子式的排列主要是化學表示法，並不等於逐一畫出的鍵結地圖；要看連接需使用結構式或模型。", "區分表示法的功能，避免把文字排列和微觀結構混為一談。", ["確認分子式提供的是元素與數量。", "確認它沒有畫出每一條連接線。", "說明結構式或模型才補充相鄰關係。", "檢查交換符號是否真的改變連接，而非只改寫法。", "所以選 A。"], "easy"),
    make(6, "以 C₂H₆O 的兩種結構為例，哪一項比較能作為區分性證據？", {"A": "一項可重現且與結構相關的性質差異，例如沸點或與水互溶程度的比較", "B": "只看樣品瓶的標籤字體", "C": "只把分子式再抄寫一次", "D": "任意猜測其中一個名稱，不需量測或模型"}, "區分兩種結構需要可重現、能與模型連結的觀察；單純標籤或重抄分子式沒有辨識力。", "挑選能排除替代模型的證據，而不是只找看起來相關的資訊。", ["先列出兩個模型共同的分子式。", "找出兩個模型真正不同的結構部位。", "選擇可能受該部位影響且可重複測量的性質。", "確認測量結果能比較兩個模型而非只描述一個樣品。", "所以選 A。"], "medium"),
    make(7, "下列何者是同分異構物判斷中最容易犯的錯誤？", {"A": "看到原子數相同就直接判定是同一物質，沒有檢查連接關係", "B": "先寫出分子式再檢查原子數", "C": "用結構模型核對每個原子的連接", "D": "承認單一物性不足以完成鑑定"}, "同分異構物的關鍵正是同組成、不同連接；只因原子數相同就判為同一物質會漏掉結構差異。", "用定義的兩個必要條件逐一檢查，而不是只抓到其中一個。", ["寫出同分異構物需要的共同條件。", "寫出還必須具備的結構差異。", "檢查選項是否只使用原子數相同這一條件。", "比較其他選項是否符合模型與證據的要求。", "所以選 A。"], "easy"),
    make(8, "研究兩個未知有機物時，甲、乙分子式相同且一項物性相同。最嚴謹的結論是？", {"A": "現有資料尚不足以判定兩者是同一物質或同分異構物，需比較結構或增加區分性證據", "B": "一項物性相同就必然是同一物質", "C": "分子式相同就必然是同分異構物", "D": "只要名稱相似就可忽略實驗資料"}, "分子式與單一物性相同仍可能有多個結構模型；需要結構資料或更多可區分的證據。", "保留證據不足的可能性，避免把未證明的推測寫成答案。", ["列出目前已知的共同資料。", "檢查是否已知原子連接或結構式。", "判斷一項物性能否排除其他模型。", "若不能，提出需要補充的結構或實驗證據。", "所以選 A。"], "hard"),
    make(9, "結構式中出現 —OH 部位，學習者最適合把它當作什麼？", {"A": "可用來比較分子間作用與物性趨勢的結構線索，但不能單獨預測所有性質", "B": "保證樣品一定無毒且可飲用的安全證明", "C": "代表分子式中所有氧原子都位於同一位置", "D": "表示樣品一定比沒有 —OH 的物質沸點低"}, "—OH 是有用的結構線索，可協助解釋氫鍵等作用與部分物性趨勢，但不能取代完整資料與安全評估。", "把結構線索的解釋力與它的適用界線同時寫出。", ["辨認 —OH 所表示的連接部位。", "說明它可能影響分子間作用。", "避免把趨勢推論擴大成所有物性的定律。", "特別排除由結構片段直接推導可飲用或無毒。", "所以選 A。"], "medium"),
    make(10, "某題給出兩個 C₂H₆O 模型與沸點資料，最佳作答順序為何？", {"A": "先核對分子式，再追蹤連接方式，最後用沸點資料比較並寫出證據限制", "B": "先猜名稱，再把所有資料改成支持猜測的內容", "C": "只看沸點，不需確認模型的原子數", "D": "只數總原子，不必區分原子如何相連"}, "正確推理要由組成到結構再到性質，並保留資料不足時的限制；只看單一層次容易過度結論。", "固定使用組成—連接—證據三層核對，但每層都要根據題目資料重新判斷。", ["先確認兩模型的元素種類與原子數。", "逐一追蹤關鍵原子相連的對象。", "將沸點資料與可能的分子間作用連結。", "寫出資料能支持的範圍與尚待驗證的部分。", "所以選 A。"], "medium"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    option_map = {o["id"]: o["text"] for o in q["options"]}
    option_map["A"], option_map[target] = option_map[target], option_map["A"]
    q["options"] = [{"id": k, "text": option_map[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A。", f"選 {target}。")
    q["solutionSteps"] = [s.replace("所以選 A。", f"所以選 {target}。") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
